import { describe, expect, it } from "vitest";
import { setPromptSection } from "./promptSections";

describe("required Pi structured prompt contract", () => {
  // Old/malformed host events cannot be generated by a supported Pi process.
  // Focused boundary tests complement the real Pi multi-extension turn tests.
  it("rejects missing or malformed section state rather than returning legacy prompt text", () => {
    for (const event of [
      {},
      { systemPrompt: "legacy" },
      { systemPromptOptions: {} },
      { systemPromptOptions: { sections: [] } },
      { systemPromptOptions: { sections: { other: false } } },
    ]) {
      expect(() =>
        setPromptSection({ event, name: "owned", content: "instructions" }),
      ).toThrow(/Pi >=0.99.1 is required/);
    }
  });

  it("replaces only its own section without changing other extensions", () => {
    const existing = { other: "another extension" };
    const event = { systemPromptOptions: { sections: { ...existing } } };
    const name = "owned";
    for (const content of ["initial", "updated"]) {
      setPromptSection({ event, name, content });
      expect(event.systemPromptOptions.sections).toEqual({
        ...existing,
        [name]: content,
      });
    }
  });
});
